questionvariables.text:
/* y = a*sin(x) or y = a*cos(x) on 0 <= x <= 2*pi.
   fs: 1 = sine, 2 = cosine; a = -5..5 without 0, giving 2 x 10 = 20 distinct graphs. */
fs : rand([1, 2]);
a : rand([-5, -4, -3, -2, -1, 1, 2, 3, 4, 5]);
trg : if fs = 1 then sin(x) else cos(x);
yexpr : a*trg;
/* base values at x = 0, pi/2, pi, 3*pi/2, 2*pi */
bsin : [0, 1, 0, -1, 0];
bcos : [1, 0, -1, 0, 1];
bs : if fs = 1 then bsin else bcos;
bo : if fs = 1 then bcos else bsin;     /* the other function: sin/cos mix-up */
yv : a*bs;
yo : a*bo;
y1 : yv[1]; y2 : yv[2]; y3 : yv[3]; y4 : yv[4]; y5 : yv[5];
o1 : yo[1]; o2 : yo[2]; o3 : yo[3]; o4 : yo[4]; o5 : yo[5];
b1 : bs[1]; b2 : bs[2]; b3 : bs[3]; b4 : bs[4]; b5 : bs[5];  /* ignored the coefficient a */
amp : abs(a);
ymax : amp;
ymin : -amp;
per : 2*%pi;
